import 'package:flutter_local_notifications/flutter_local_notifications.dart';
class NotificationService{NotificationService._();static final instance=NotificationService._();final plugin=FlutterLocalNotificationsPlugin();
Future<void> initialize()async{const android=AndroidInitializationSettings('@mipmap/ic_launcher');const ios=DarwinInitializationSettings(requestAlertPermission:true,requestBadgePermission:true,requestSoundPermission:true);await plugin.initialize(const InitializationSettings(android:android,iOS:ios));}
Future<void> requestPermissions()async{await plugin.resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>()?.requestNotificationsPermission();await plugin.resolvePlatformSpecificImplementation<IOSFlutterLocalNotificationsPlugin>()?.requestPermissions(alert:true,badge:true,sound:true);}
Future<void> showDue(int id,String title,String? tag)=>plugin.show(id,'OPERON timer due',tag==null?title:'$tag · $title',const NotificationDetails(android:AndroidNotificationDetails('operon_timers','Operator timers',channelDescription:'Operational timer reminders',importance:Importance.high,priority:Priority.high),iOS:DarwinNotificationDetails()));}
